<template lang="pug">
.data-table(:style="{ height: height }")
    .data-table-bar
        el-input.data-table-search(v-model="q" size="large" prefix-icon="Search" :placeholder="searchPlaceholder" clearable @input="onSearchInput")
        .data-table-toolbar
            slot(name="toolbar")
    .data-table-frame(ref="frame")
        el-table(:data="rows" :height="tableHeight" v-loading="loading" stripe border style="width: 100%" @sort-change="onSortChange")
            slot
    .data-table-footer
        el-pagination(
            background
            layout="total, sizes, prev, pager, next, jumper"
            :total="total"
            :page-sizes="[20, 50, 100, 200]"
            v-model:current-page="page"
            v-model:page-size="pageSize"
            @current-change="load"
            @size-change="onSizeChange")
</template>

<script>
// Server-driven table: owns page/size/search/sort state, calls `fetchFn` for one
// page at a time, and renders whatever columns the parent puts in the default
// slot. The table body scrolls inside a fixed-height frame so the pagination bar
// stays in view instead of being pushed below the fold.
export default {
    name: 'DataTable',
    props: {
        // async ({page, pageSize, q, sort, order}) => { data: [...], meta: { total } }
        fetchFn: { type: Function, required: true },
        defaultPageSize: { type: Number, default: 50 },
        searchPlaceholder: { type: String, default: '搜尋' },
        // Overall component height; the table body fills what's left after the
        // search bar and pagination, so the footer is always visible.
        height: { type: String, default: 'calc(100vh - 190px)' }
    },
    data() {
        return {
            rows: [],
            total: 0,
            page: 1,
            pageSize: this.defaultPageSize,
            q: '',
            sort: '',
            order: '',
            loading: false,
            searchTimer: null,
            tableHeight: 400
        }
    },
    created() {
        this.load()
    },
    mounted() {
        this.measure()
        this._onResize = () => this.measure()
        window.addEventListener('resize', this._onResize)
    },
    beforeUnmount() {
        window.removeEventListener('resize', this._onResize)
    },
    methods: {
        measure() {
            // Fit the el-table scroll area to the frame so its sticky header works
            // and the footer never gets pushed off-screen.
            this.$nextTick(() => {
                if (this.$refs.frame) this.tableHeight = this.$refs.frame.clientHeight
            })
        },
        async load() {
            this.loading = true
            try {
                const res = await this.fetchFn({
                    page: this.page,
                    pageSize: this.pageSize,
                    q: this.q,
                    sort: this.sort,
                    order: this.order
                })
                this.rows = (res && res.data) || []
                this.total = res && res.meta ? res.meta.total : this.rows.length
                this.$emit('loaded', this.rows)
            } catch (error) {
                console.error(error)
                this.rows = []
                this.total = 0
            } finally {
                this.loading = false
            }
        },
        onSearchInput() {
            // Debounce: a page reset + reload 300ms after the user stops typing.
            clearTimeout(this.searchTimer)
            this.searchTimer = setTimeout(() => {
                this.page = 1
                this.load()
            }, 300)
        },
        onSizeChange() {
            this.page = 1
            this.load()
        },
        onSortChange({ prop, order }) {
            // Element Plus emits 'ascending' | 'descending' | null.
            this.sort = order ? prop : ''
            this.order = order === 'descending' ? 'DESC' : 'ASC'
            this.page = 1
            this.load()
        },
        // Public: refetch. Pass true after a filter change to jump back to page 1;
        // omit after a row mutation to stay on the current page.
        reload(resetPage = false) {
            if (resetPage) this.page = 1
            this.load()
        }
    }
}
</script>
