<template lang="pug">
.page-container
    el-row(:gutter="20")
        el-col(:sm="24" :md="12")
            .page-title 心理師列表
            DataTable(ref="table" :fetch-fn="fetchPage" search-placeholder="搜尋姓名")
                template(#toolbar)
                    select.labelSelector(v-model='semester_label' @change="onSemesterChange")
                        option(value='') 全部學期
                        option(v-for='option in labelOption' :key='option.label' :value='option.label') {{ option.label }}
                el-table-column(prop="name" label="姓名")
                el-table-column(prop="gender" label="性別" width="60")
                el-table-column(label="聘用類別" width="90")
                    template(#default='scope')
                        span(v-if="scope.row.employment_type") {{scope.row.employment_type}}
                        el-tag(v-else type="warning" size="small") 未設定
                el-table-column(prop="semester_label" label="學期")
                el-table-column(prop="available_time" label="可諮商時段")
                    template(#header='')
                        el-popover(placement="right" title="" :width="200" trigger="hover" popper-class="weektimePop")
                            div(v-html="getHtmlContent()")
                            template(#reference)
                                span 可諮商時段
                                    QuestionFilled(style="width: 1em; height: 1em; padding: 0 0 0 3px")
                    template(#default='scope')
                        div {{scope.row.available_time}}
                el-table-column(label="功能按鈕" align="center" width="140" fixed="right")
                    template(v-slot:default="slotProps")
                        .cell-actions
                            el-button(type="primary" size="small"  @click="modifyCase(slotProps.row.id)") 修改
                            el-button(type="danger" size="small" @click="clickDelete(slotProps.row.id)") 刪除
        el-col(:sm="24" :md="12")
            router-view(v-slot="{ Component }" @modified='getCounselor()')
                transition(name="scale" mode="out-in")
                    component(:is="Component")
</template>

<script>
import {weektimeMixin} from "@/components/weektimeMixin"
import DataTable from '@/components/DataTable.vue';
export default {
    mixins: [weektimeMixin],
    components: {DataTable},
    data () {
        return {
            semester_label: '',
            labelOption: [],
        }
    },
    async created() {
        await this.$store.dispatch('fetchSemesterLabel')
        this.labelOption = this.$store.state.semester_label.data
    },
    methods: {
        async fetchPage({ page, pageSize, q, sort, order }) {
            const res = await this.$http.get('/api/counselor', {
                params: { semester_label: this.semester_label, page, pageSize, q, sort, order }
            })
            return { data: res.data.data, meta: res.data.meta }
        },
        onSemesterChange() {
            if (this.$refs.table) this.$refs.table.reload(true)
        },
        getCounselor() {
            if (this.$refs.table) this.$refs.table.reload()
        },
        deleteCounselor(id) {
            this.$http.delete("/api/counselor/"+id)
            .then(() => {
                this.$message({
                    type: 'success',
                    message: '刪除成功!'
                });
                this.getCounselor()
            })
            .catch((error) => {
                //發送請求失敗時
                console.error(error)
            });
        },
        clickDelete(id) {
            this.$confirm('將永久刪除此筆資料, 是否繼續?', '提示', {
                confirmButtonText: '確定',
                cancelButtonText: '取消',
                type: 'warning'
                }).then(() => {
                    this.deleteCounselor(id)
                }).catch(() => {
                this.$message({
                    type: 'info',
                    message: '已取消刪除'
                })         
            })
        },
        modifyCase(id) {
            this.$router.push('/manageCounselor/modify/'+id)
        }
    }
}
</script>
<style>
.scale-enter-active,
.scale-leave-active {
  transition: all 0.2s ease;
}
.scale-enter-from,
.scale-leave-to {
  opacity: 0;
  transform: scale(0.6);
}
</style>
<style lang="sass" scoped>
@import "@/style/common.sass"
.labelSelector
    margin: 0 10px 10px 0

</style>
